package com.example.editor.integration.adapter.emf;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import com.example.editor.integration.IntegrationArtifactKind;
import com.example.editor.integration.compiler.TechnologyAdapterTestFixtures;
import com.example.editor.integration.compiler.TechnologyCompilationRequest;
import com.example.editor.integration.projection.CanonicalArtifactContent;

class EmfTechnologyAdapterTests {
    private final EmfTechnologyAdapter adapter=new EmfTechnologyAdapter(TechnologyAdapterTestFixtures.MAPPER,TechnologyAdapterTestFixtures.ecoreAdapter());
    @Test void targetsEmf(){assertThat(adapter.technology().name()).isEqualTo("EMF");}
    @Test void generatesEcoreAndMavenModule(){var result=adapter.compile(TechnologyAdapterTestFixtures.emfRequest());assertThat(result.files()).extracting(file->file.relativePath()).anyMatch(path->path.endsWith("people.ecore")).anyMatch(path->path.endsWith("pom.xml"));}
    @Test void generatesTransactionalRuntimeAndConcreteCapabilityFacades(){var result=adapter.compile(TechnologyAdapterTestFixtures.emfRequest());var paths=result.files().stream().map(file->file.relativePath()).toList();assertThat(paths).anyMatch(value->value.endsWith("HydraSemanticRuntime.java")).anyMatch(value->value.endsWith("HydraEmfRuntime.java")).anyMatch(value->value.endsWith("HydraEmfValidationAdapter.java")).anyMatch(value->value.endsWith("HydraEmfQuickFixCommand.java")).anyMatch(value->value.endsWith("HydraEmfOperationAdapter.java")).anyMatch(value->value.endsWith("HydraEmfEventAdapter.java")).anyMatch(value->value.endsWith("HydraEmfEditingDomain.java"));var combined=result.files().stream().filter(file->file.relativePath().endsWith(".java")).map(file->new String(file.content(),StandardCharsets.UTF_8)).reduce("",String::concat);assertThat(combined).contains("extends ChangeCommand","new ChangeRecorder","HydraEmfRuntime.synchronize","public void undo(EObject root)","public void redo(EObject root)").doesNotContain("extends AdapterImpl");}
    @Test void embedsCanonicalDocuments(){var result=adapter.compile(TechnologyAdapterTestFixtures.emfRequest());assertThat(result.files()).extracting(file->file.relativePath()).anyMatch(path->path.contains("src/main/resources/hydra/metamodel.json"));}
    @Test void declaresCurrentNativeEmfDependencies(){var result=adapter.compile(TechnologyAdapterTestFixtures.emfRequest());assertThat(result.dependencies()).extracting(value->value.coordinate()).contains("org.eclipse.emf:org.eclipse.emf.ecore","org.eclipse.emf:org.eclipse.emf.ecore.change","org.eclipse.emf:org.eclipse.emf.edit");assertThat(result.dependencies()).extracting(value->value.version()).contains("2.46.0","2.43.0","2.41.0","2.18.0","2.24.0");}
    @Test void includesMavenVerification(){assertThat(adapter.compile(TechnologyAdapterTestFixtures.emfRequest()).verificationSteps()).singleElement().satisfies(step->assertThat(step.command()).containsExactly("mvn","-q","test"));}
    @Test void producesDeterministicPathsAndContent(){var first=adapter.compile(TechnologyAdapterTestFixtures.emfRequest());var second=adapter.compile(TechnologyAdapterTestFixtures.emfRequest());assertThat(first.files()).usingRecursiveComparison().isEqualTo(second.files());}
    @Test void usesConfiguredBasePackage(){var source=TechnologyAdapterTestFixtures.emfRequest();var target=new com.example.editor.integration.IntegrationTarget(source.profile().target().technology(),source.profile().target().kind(),"","host","people-emf",source.profile().target().buildSystem(),List.of(),List.of(),"",Map.of("basePackage","org.example.people.emf"));var profile=new com.example.editor.integration.IntegrationProfileModel(source.profile().schemaVersion(),source.profile().id(),source.profile().metamodelId(),source.profile().name(),target,source.profile().deliveryMode(),source.profile().features(),source.profile().artifacts(),source.profile().mappings(),source.profile().injectionPolicy(),source.profile().requiredCapabilities(),source.profile().annotations());var result=adapter.compile(new TechnologyCompilationRequest(profile,source.artifacts(),"test",Map.of()));assertThat(result.metadata()).containsEntry("basePackage","org.example.people.emf");assertThat(result.files()).extracting(file->file.relativePath()).anyMatch(path->path.contains("org/example/people/emf"));}
    @Test void rejectsMissingMetamodel(){var source=TechnologyAdapterTestFixtures.emfRequest();assertThatThrownBy(()->adapter.compile(new TechnologyCompilationRequest(source.profile(),List.of(),"test",Map.of()))).hasMessageContaining("METAMODEL");}
    @Test void reportsNotationAsUnsupported(){var source=TechnologyAdapterTestFixtures.emfRequest();var artifacts=new ArrayList<>(source.artifacts());artifacts.add(new CanonicalArtifactContent(IntegrationArtifactKind.NOTATION,"notation","application/json","{}".getBytes(StandardCharsets.UTF_8)));var result=adapter.compile(new TechnologyCompilationRequest(source.profile(),artifacts,"test",Map.of()));assertThat(result.diagnostics()).extracting(value->value.code()).contains("UNSUPPORTED_ARTIFACT");}
    @Test void keepsGeneratedFilesUnderConfiguredRoot(){assertThat(adapter.compile(TechnologyAdapterTestFixtures.emfRequest()).files()).allSatisfy(file->assertThat(file.relativePath()).startsWith("generated-integration/people-emf/"));}
    @Test void documentsCanonicalSourceOfTruth(){var readme=adapter.compile(TechnologyAdapterTestFixtures.emfRequest()).files().stream().filter(file->file.relativePath().endsWith("README.md")).findFirst().orElseThrow();assertThat(new String(readme.content(),StandardCharsets.UTF_8)).contains("MetaModel 2.1","HydraSemanticRuntime","Events → EventFlow → Gamification","Raw EMF notifications are not treated as commits").doesNotContain("Ecore is the source of truth");}
}
